<?php
/** Proof — transfers (spec "Proof", 4): Checking → Card 500: both balances move, a candidate on both accounts' lines signed each way; void refused while matched. */
require __DIR__ . '/lib.php';
$bea = as_member(27); $carl = as_member(28); $vera = as_member(26);
$w = cash_world();
pdo()->exec("SELECT set_config('app.member_id', '1', false)");
$bal = fn (int $b): array => ['ledger' => (string) one('SELECT ledger_balance FROM mcp_bank_accounts WHERE bank_account_id = :b', ['b' => $b]), 'cleared' => (string) one('SELECT cleared_balance FROM mcp_bank_accounts WHERE bank_account_id = :b', ['b' => $b])];
echo "1. Record\n";
$chk0 = $bal($w['chk']); $card0 = $bal($w['card']);
$body = page($bea, '/cash/transfers/new?from=' . $w['chk'] . '&to=' . $w['card'])['body'];
ok(str_contains($body, 'id="transfer-form"') && str_contains($body, 'id="transfer-form-field-from"') && str_contains($body, 'id="transfer-form-field-amount"') && preg_match('/<option value="' . $w['chk'] . '" selected>/', $body) === 1, 'the form, with ?from= and ?to= chosen');
$since = last_activity_id();
[$c, $b] = act($bea, '/cash/transfers/save.php', ['from_bank_account' => $w['chk'], 'to_bank_account' => $w['card'], 'amount' => '500', 'transfer_date' => '2026-06-05', 'memo' => 'SMOKE card payment']);
$t = (int) ($b['record_id'] ?? 0);
ok($c === 200 && $t > 0 && ($b['location'] ?? '') === '/cash/transfers/' . $t . '?notice=recorded' && preg_match('/^TRF-\d{6}$/', (string) ($b['number'] ?? '')) === 1, "transfer_record: 200, record_id $t, a number at creation (" . ($b['number'] ?? '?') . ')');
$row = q('SELECT * FROM transfers WHERE id = :t', ['t' => $t])[0];
ok($row['status'] === 'recorded' && $row['amount'] === '500.00' && $row['currency'] === 'USD' && (int) $row['from_bank_account_id'] === $w['chk'] && (int) $row['to_bank_account_id'] === $w['card'] && $row['journal_entry_id'] !== null && (int) $row['recorded_by'] === 27, 'recorded by 27: 500.00 USD from Checking to the Card, posted');
$jl = array_column(q('SELECT a.code, l.debit, l.credit FROM journal_lines l JOIN accounts a ON a.id = l.account_id WHERE l.entry_id = :e', ['e' => $row['journal_entry_id']]), null, 'code');
ok($jl['2300']['debit'] === '500.00' && $jl['1010']['credit'] === '500.00', 'the entry: DR 2300 (the receiving card) 500.00 / CR 1010 (the sending checking) 500.00');
pdo()->exec("SELECT set_config('app.member_id', '1', false)");
$chk1 = $bal($w['chk']); $card1 = $bal($w['card']);
ok(m_sub($chk0['ledger'], $chk1['ledger']) === '500.00' && m_sub($card0['ledger'], $card1['ledger']) === '500.00', 'both bank accounts\' ledger balances move by 500.00 (Checking down; the card\'s owed balance down)');
$l = activity('transfer.record', $since)[0]; $a = json_decode((string) $l['after'], true);
ok((int) $l['bank_account_id'] === $w['chk'] && (int) $l['journal_entry_id'] === (int) $row['journal_entry_id'] && $a['number'] === $row['number'] && $a['amount'] === '500.00' && $a['currency'] === 'USD' && $a['from_bank_account_id'] === $w['chk'] && $a['to_bank_account_id'] === $w['card'], 'transfer.record logs number, amount, currency, both account ids, bank_account_id (the sender) and journal_entry_id');
echo "2. The guards\n";
[$c, $b] = act($bea, '/cash/transfers/save.php', ['from_bank_account' => $w['chk'], 'to_bank_account' => $w['chk'], 'amount' => '1']);
ok($c === 422 && str_contains(msg($b), 'between two different bank accounts'), 'to itself: 422 "A transfer is between two different bank accounts."');
if (!one("SELECT 1 FROM accounts WHERE code = '1040'")) { q("INSERT INTO accounts (code, name, account_type, subtype, is_bank, is_control, is_system) VALUES ('1040', 'SMOKE Euro cash', 'asset', 'cash', true, false, false)"); }
$eur = (int) (one("SELECT id FROM bank_accounts WHERE name = 'SMOKE Euro cash'") ?: one("INSERT INTO bank_accounts (name, kind, account_id, currency, opening_balance, opening_date, created_by) VALUES ('SMOKE Euro cash', 'cash', :a, 'EUR', 0, '2026-01-01', 1) RETURNING id", ['a' => account_id('1040')]));
[$c, $b] = act($bea, '/cash/transfers/save.php', ['from_bank_account' => $w['chk'], 'to_bank_account' => $eur, 'amount' => '1']);
ok($c === 422 && str_contains(msg($b), 'A transfer between currencies is not recorded here'), 'between currencies: 422 "A transfer between currencies is not recorded here"');
[$c, $b] = act($bea, '/cash/transfers/save.php', ['from_bank_account' => $w['chk'], 'to_bank_account' => $w['card'], 'amount' => '0', 'transfer_date' => 'x']);
ok($c === 422 && isset(fields($b)['amount'], fields($b)['transfer_date']), 'a zero amount and a bad date: 422 naming both');
[$c, $b] = act($bea, '/cash/transfers/save.php', ['from_bank_account' => 424242, 'to_bank_account' => $w['card'], 'amount' => '5']);
ok($c === 422 && isset(fields($b)['from_bank_account']), 'a bank account that is not there: 422');
[$c, $b] = act($vera, '/cash/transfers/save.php', ['from_bank_account' => $w['chk'], 'to_bank_account' => $w['card'], 'amount' => '5']);
ok($c === 403, 'a Viewer recording: 403');
echo "3. A candidate on both accounts' lines, signed each way\n";
$lc = bank_line_row($w['chk'], '2026-06-06', '-500.00', 'SMOKE CARD PAYMENT OUT', 'TR-OUT');
$lk = bank_line_row($w['card'], '2026-06-06', '500.00', 'SMOKE PAYMENT RECEIVED', 'TR-IN');
$cand = function (int $bank, int $line) use ($bea): array { $d = screen($bea, '/cash/match?bank_account=' . $bank)[1]; foreach ($d['lines'] ?? [] as $x) { if ($x['bank_transaction_id'] === $line) { return $x['candidates']; } } return []; };
$c1 = $cand($w['chk'], $lc); $c2 = $cand($w['card'], $lk);
ok(count($c1) === 1 && $c1[0]['item_type'] === 'transfer' && $c1[0]['item_id'] === $t && $c1[0]['amount'] === '-500.00', 'on Checking the transfer is a candidate for the −500.00 line');
ok(count($c2) === 1 && $c2[0]['item_type'] === 'transfer' && $c2[0]['item_id'] === $t && $c2[0]['amount'] === '500.00', 'on the Card it is a candidate for the +500.00 line');
[$c, $b] = act($bea, '/cash/match.php', ['bank_line' => $lc, 'item_type' => 'transfer', 'item' => $t]);
ok($c === 200 && line_status($lc) === 'matched', 'matched on Checking');
[$c, $b] = act($bea, '/cash/match.php', ['bank_line' => $lk, 'item_type' => 'transfer', 'item' => $t]);
ok($c === 200 && line_status($lk) === 'matched', 'and on the Card (the same transfer, once per account)');
$wrongSign = bank_line_row($w['chk'], '2026-06-06', '500.00', 'SMOKE WRONG SIGN', 'TR-BAD');
[$c, $b] = act($bea, '/cash/match.php', ['bank_line' => $wrongSign, 'item_type' => 'transfer', 'item' => $t]);
ok($c === 422 && str_contains(msg($b), 'a match is to the cent'), 'a +500.00 line on Checking does not match the outgoing transfer: 422 "… a match is to the cent"');
$body = page($bea, '/cash/transfers/' . $t)['body'];
ok(str_contains($body, 'id="transfer-matched-' . $lc . '"') && str_contains($body, 'id="transfer-matched-' . $lk . '"') && str_contains($body, 'id="transfer-head-entry-link"'), 'the transfer page lists both matched lines and its entry');
echo "4. Void\n";
[$c, $b] = act($bea, '/cash/transfers/void.php', ['transfer' => $t, 'reason' => 'x']);
ok($c === 403 && msg($b) === 'You may not reverse, void or write off.', 'a Bookkeeper voiding: 403');
[$c, $b] = act($carl, '/cash/transfers/void.php', ['transfer' => $t, 'reason' => 'SMOKE x']);
ok($c === 422 && str_contains(msg($b), 'is matched to a bank line; unmatch it first'), 'void refused while matched: "… is matched to a bank line; unmatch it first"');
act($bea, '/cash/unmatch.php', ['bank_line' => $lc]); act($bea, '/cash/unmatch.php', ['bank_line' => $lk]);
[$c, $b] = act($carl, '/cash/transfers/void.php', ['transfer' => $t, 'reason' => '']);
ok($c === 422 && str_contains(msg($b), 'Voiding a transfer needs a reason'), 'no reason: 422');
$since = last_activity_id();
[$c, $b] = act($carl, '/cash/transfers/void.php', ['transfer' => $t, 'reason' => 'SMOKE entered twice']);
$row = q('SELECT * FROM transfers WHERE id = :t', ['t' => $t])[0];
ok($c === 200 && $row['status'] === 'void' && $row['void_reason'] === 'SMOKE entered twice' && (int) one('SELECT count(*) FROM journal_entries WHERE reversal_of = :e', ['e' => $row['journal_entry_id']]) === 1, 'unmatched, it is voided: the entry reversed, the reason kept');
pdo()->exec("SELECT set_config('app.member_id', '1', false)");
ok(m_cmp($bal($w['chk'])['ledger'], $chk0['ledger']) === 0 && m_cmp($bal($w['card'])['ledger'], $card0['ledger']) === 0, 'both balances are back where they were (' . json_encode([$chk0, $bal($w['chk']), $card0, $bal($w['card'])]) . ')');
$l = activity('transfer.void', $since)[0]; $a = json_decode((string) $l['after'], true);
ok($a['reason'] === 'SMOKE entered twice' && $a['amount'] === '500.00' && (int) $l['bank_account_id'] === $w['chk'], 'transfer.void logs the reason and amount');
[$c, $b] = act($carl, '/cash/transfers/void.php', ['transfer' => $t, 'reason' => 'again']);
ok($c === 422 && str_contains(msg($b), 'is already void'), 'voiding twice: 422');
$cand2 = $cand($w['chk'], $wrongSign);
ok($cand2 === [], 'a void transfer is no longer a candidate');
echo "5. The pages\n";
$t2 = (int) act($bea, '/cash/transfers/save.php', ['from_bank_account' => $w['chk'], 'to_bank_account' => $w['cash'], 'amount' => '75.25', 'transfer_date' => '2026-06-07'])[1]['record_id'];
$body = page($bea, '/cash/transfers/')['body'];
ok(str_contains($body, 'id="transfer-card-' . $t . '"') && str_contains($body, 'id="transfer-card-' . $t2 . '"') && str_contains($body, 'SMOKE Checking'), 'the list: a card per transfer');
$d = screen($bea, '/cash/transfers/?bank_account=' . $w['cash'])[1];
ok(array_column($d['transfers'] ?? [], 'transfer_id') === [$t2], 'filtered by bank account');
$d = screen($bea, '/cash/transfers/' . $t)[1];
ok(($d['transfer']['status'] ?? '') === 'void' && ($d['transfer']['amount'] ?? '') === '500.00' && ($d['transfer']['from']['name'] ?? '') === 'SMOKE Checking' && isset($d['may']), 'JSON: the transfer with its accounts');
$d = screen($bea, '/cash/banks/' . $w['cash'])[1];
ok(count($d['transfers'] ?? []) >= 1 && ($d['transfers'][0]['transfer_id'] ?? 0) === $t2, 'the bank account page lists its transfers');
finish();
